from signup import SignupPayload, validate_signup


def test_happy_path_valid_corporate_signup():
    payload = SignupPayload(
        email="engineer@acme.com",
        password="StrongPass123",
        accepted_terms=True,
    )
    assert validate_signup(payload) == {"ok": True, "reason": "accepted"}


def test_edge_case_email_whitespace_is_normalized():
    payload = SignupPayload(
        email="  user@company.io  ",
        password="Password99",
        accepted_terms=True,
    )
    assert validate_signup(payload) == {"ok": True, "reason": "accepted"}


def test_boundary_condition_password_length_eight_is_allowed():
    payload = SignupPayload(
        email="qa@startup.dev",
        password="abcd1234",
        accepted_terms=True,
    )
    assert validate_signup(payload) == {"ok": True, "reason": "accepted"}


def test_unexpected_input_malformed_email_is_rejected():
    payload = SignupPayload(
        email="not-an-email",
        password="StrongPass123",
        accepted_terms=True,
    )
    assert validate_signup(payload) == {"ok": False, "reason": "invalid_email"}
